// Maps a stationery product to its illustration in /public/products.
// The images are generated by scripts/gen-product-images.mjs; the AVAILABLE
// table below must match the combinations that script writes.

const AVAILABLE: Record<string, string[]> = {
  sheets: ["white", "brown"], ruled: ["blue"], graph: ["green"], sticky: ["yellow", "multi"],
  card: ["blue"], booklet: ["blue"], notebook: ["blue", "red", "green", "orange", "black"], spiral: ["blue", "red"],
  file: ["blue", "red", "green"], folder: ["blue", "green"], binder: ["blue", "black"], envelope: ["brown", "white"],
  bag: ["blue", "green"], display: ["blue", "black"], tabs: ["multi"], cover: ["blue"], strip: ["blue"],
  pen: ["blue", "black", "red", "green"], marker: ["blue", "black", "red", "green"],
  pencil: ["yellow", "black"], highlighter: ["yellow", "pink", "green", "orange", "blue", "multi"],
  eraser: ["white", "blue"], sharpener: ["blue", "red"], pencilset: ["multi"], boxset: ["multi"], crayon: ["multi"],
  bottle: ["blue"], tape: ["white", "brown"], glue: ["blue", "red"], tube: ["white", "red"],
  stapler: ["blue", "red"], pins: ["blue", "red"], clip: ["blue", "red"], bclip: ["blue", "red"], rubber: ["blue", "red"],
  scissors: ["blue", "red"], ruler: ["blue", "red"], setsquare: ["blue", "red"], protractor: ["blue", "red"],
  compass: ["blue", "red"], geobox: ["blue", "red"], calc: ["blue", "red"], punch: ["blue", "red"], tack: ["blue", "red"],
  penstand: ["blue", "red"], label: ["blue", "red"], lanyard: ["blue", "red"], board: ["blue", "red"], box: ["blue", "red"],
};

// First matching rule wins, so order matters (specific before generic).
const RULES: [RegExp, string][] = [
  [/sticky|post-?it/, "sticky"], [/index card/, "card"], [/booklet|supplementary/, "booklet"],
  [/graph (paper|sheet)/, "graph"], [/ruled sheet/, "ruled"], [/graph notebook/, "notebook"],
  [/brown paper|butter|tracing|carbon|chart paper|drawing sheet|a[0-9] sheet/, "sheets"],
  [/spiral/, "spiral"], [/notebook|lab manual|diary|register|drawing book/, "notebook"],
  [/project file|lab file/, "file"],
  [/pencil lead|mechanical pencil/, "pencil"], [/color pencil|colour pencil/, "pencilset"],
  [/pencil.*pack|pack.*pencil/, "pencilset"], [/pencil/, "pencil"],
  [/sketch pen|oil pastel/, "boxset"], [/crayon/, "crayon"], [/pen set/, "boxset"],
  [/ink bottle|ink cartridge/, "bottle"], [/highlighter/, "highlighter"],
  [/whitener|correction/, "tube"], [/marker/, "marker"], [/fountain|ink pen|\bpen\b/, "pen"],
  [/eraser/, "eraser"], [/sharpener/, "sharpener"],
  [/staple remover|stapler|stapler pin/, "stapler"], [/pins? no\./, "pins"],
  [/glue|fevi/, "glue"], [/tape dispenser|tape/, "tape"], [/binder clip/, "bclip"], [/paper clip/, "clip"],
  [/rubber band/, "rubber"], [/scissors|cutter|blade/, "scissors"], [/scale|ruler/, "ruler"],
  [/set square/, "setsquare"], [/protractor/, "protractor"], [/compass/, "compass"], [/geometry box/, "geobox"],
  [/calculator/, "calc"], [/punch/, "punch"], [/push pin|thumb tack|drawing pin/, "tack"],
  [/pen stand|holder/, "penstand"], [/label/, "label"], [/lanyard|id card/, "lanyard"], [/exam pad|writing board/, "board"],
  [/envelope/, "envelope"], [/ring binder/, "binder"], [/display book/, "display"], [/document bag/, "bag"],
  [/separator|tabs/, "tabs"], [/plastic cover/, "cover"], [/binding strip/, "strip"],
  [/folder|spring file|box file|report file|stick file|expanding file|certificate/, "folder"],
];

const COLOR_WORDS = ["blue", "black", "red", "green", "yellow", "pink", "orange", "brown", "white"];

export function productImage(name: string, imageUrl?: string | null): string {
  if (imageUrl) return imageUrl;
  const n = name.toLowerCase();
  const type = RULES.find(([re]) => re.test(n))?.[1];
  if (!type) return "/products/box-blue.svg";

  const options = AVAILABLE[type];
  let color = /neon|colou?red|set|pack/.test(n) && options.includes("multi") ? "multi" : COLOR_WORDS.find((c) => n.includes(c));
  if (!color || !options.includes(color)) color = options[0];
  return `/products/${type}-${color}.svg`;
}
